begin;set local role postgres;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions,pgtap;select plan(96);
select ok(to_regclass('public.erp_command_receipts')is not null,'command receipts table exists');
select ok((select relrowsecurity from pg_class where oid='public.erp_command_receipts'::regclass),'command receipts RLS enabled');
select ok(not has_table_privilege('anon','public.erp_command_receipts','SELECT'),'anon cannot read receipts');
select ok(not has_table_privilege('authenticated','public.erp_command_receipts','SELECT'),'authenticated cannot read receipts directly');
select ok(not has_table_privilege('authenticated','public.erp_command_receipts','INSERT'),'authenticated cannot insert receipts directly');
select ok(exists(select 1 from information_schema.columns where table_schema='public'and table_name='erp_command_receipts'and column_name=n),format('receipt column %s exists',n))from unnest(array['id','tenant_id','command_type','request_id','payload_hash','status','result_json','actor_id','created_at','completed_at'])n;
select ok(exists(select 1 from pg_constraint where conrelid='public.erp_command_receipts'::regclass and contype=t),format('receipt constraint type %s exists',t))from unnest(array['p','u','f','c'])t;
select ok(to_regprocedure(signature)is not null,format('%s exists',signature))from unnest(array['public.erp_require_command_access_v1(uuid,text,text)','public.erp_claim_command_v1(uuid,text,text,text,jsonb)','public.erp_complete_command_v1(uuid,uuid,jsonb)','public.erp_command_create_party_v1(uuid,text,text,jsonb)','public.erp_command_create_catalog_item_v1(uuid,text,text,jsonb)','public.erp_command_receive_inventory_v1(uuid,text,text,jsonb)','public.erp_command_open_cash_v1(uuid,text,text,jsonb)','public.erp_command_complete_sale_v1(uuid,text,text,jsonb)','public.erp_command_settle_receivable_v1(uuid,text,text,jsonb)','public.erp_command_close_cash_v1(uuid,text,text,jsonb)'])signature;
select ok(p.prosecdef,format('%s security definer',p.proname))from pg_proc p where p.oid=any(array['public.erp_require_command_access_v1(uuid,text,text)'::regprocedure,'public.erp_claim_command_v1(uuid,text,text,text,jsonb)'::regprocedure,'public.erp_complete_command_v1(uuid,uuid,jsonb)'::regprocedure,'public.erp_command_create_party_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_create_catalog_item_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_receive_inventory_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_open_cash_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_complete_sale_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_settle_receivable_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_close_cash_v1(uuid,text,text,jsonb)'::regprocedure])order by p.proname;
select ok(exists(select 1 from unnest(p.proconfig)c where c like'search_path=%'and c not like'%public%'),format('%s has empty search path',p.proname))from pg_proc p where p.oid=any(array['public.erp_require_command_access_v1(uuid,text,text)'::regprocedure,'public.erp_claim_command_v1(uuid,text,text,text,jsonb)'::regprocedure,'public.erp_complete_command_v1(uuid,uuid,jsonb)'::regprocedure,'public.erp_command_create_party_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_create_catalog_item_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_receive_inventory_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_open_cash_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_complete_sale_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_settle_receivable_v1(uuid,text,text,jsonb)'::regprocedure,'public.erp_command_close_cash_v1(uuid,text,text,jsonb)'::regprocedure])order by p.proname;
select ok(not has_function_privilege('anon',signature,'EXECUTE'),format('anon cannot execute %s',signature))from unnest(array['public.erp_command_create_party_v1(uuid,text,text,jsonb)','public.erp_command_create_catalog_item_v1(uuid,text,text,jsonb)','public.erp_command_receive_inventory_v1(uuid,text,text,jsonb)','public.erp_command_open_cash_v1(uuid,text,text,jsonb)','public.erp_command_complete_sale_v1(uuid,text,text,jsonb)','public.erp_command_settle_receivable_v1(uuid,text,text,jsonb)','public.erp_command_close_cash_v1(uuid,text,text,jsonb)'])signature;
select ok(has_function_privilege('authenticated',signature,'EXECUTE'),format('authenticated executes %s',signature))from unnest(array['public.erp_command_create_party_v1(uuid,text,text,jsonb)','public.erp_command_create_catalog_item_v1(uuid,text,text,jsonb)','public.erp_command_receive_inventory_v1(uuid,text,text,jsonb)','public.erp_command_open_cash_v1(uuid,text,text,jsonb)','public.erp_command_complete_sale_v1(uuid,text,text,jsonb)','public.erp_command_settle_receivable_v1(uuid,text,text,jsonb)','public.erp_command_close_cash_v1(uuid,text,text,jsonb)'])signature;
select ok(not has_function_privilege('authenticated',signature,'EXECUTE'),format('authenticated cannot execute helper %s',signature))from unnest(array['public.erp_require_command_access_v1(uuid,text,text)','public.erp_claim_command_v1(uuid,text,text,text,jsonb)','public.erp_complete_command_v1(uuid,uuid,jsonb)'])signature;
select ok(has_function_privilege('service_role',signature,'EXECUTE'),format('service role executes helper %s',signature))from unnest(array['public.erp_require_command_access_v1(uuid,text,text)','public.erp_claim_command_v1(uuid,text,text,text,jsonb)','public.erp_complete_command_v1(uuid,uuid,jsonb)'])signature;
select is((select count(*)::integer from unnest(array['party.create','catalog.item.create','inventory.receive','cash.open','sale.complete','finance.receivable.settle','cash.close'])x),7,'seven command types contracted');
select is((select count(*)::integer from public.erp_command_receipts),0,'zero command receipts before fixtures');
select ok(pg_get_functiondef('public.erp_claim_command_v1(uuid,text,text,text,jsonb)'::regprocedure)like'%pg_advisory_xact_lock%','claim serializes concurrent requests');
select ok(pg_get_functiondef('public.erp_claim_command_v1(uuid,text,text,text,jsonb)'::regprocedure)like'%idempotency conflict%','claim rejects divergent hash');
select ok(pg_get_functiondef('public.erp_claim_command_v1(uuid,text,text,text,jsonb)'::regprocedure)like'%extensions.digest%','claim computes hash with qualified pgcrypto function');
select ok(pg_get_functiondef('public.erp_claim_command_v1(uuid,text,text,text,jsonb)'::regprocedure)like'%v_computed_hash%','database-computed hash is authoritative');
select ok(pg_get_functiondef('public.erp_claim_command_v1(uuid,text,text,text,jsonb)'::regprocedure)like'%unsafe command payload%','claim rejects oversized or secret payload');
select ok(pg_get_functiondef('public.erp_command_receive_inventory_v1(uuid,text,text,jsonb)'::regprocedure)like'%inventory target unavailable%','inventory requires tracked item and active location');
select ok(pg_get_functiondef('public.erp_command_complete_sale_v1(uuid,text,text,jsonb)'::regprocedure)like'%erp_financial_entries%','store credit creates financial entry atomically');
select ok(pg_get_functiondef('public.erp_command_complete_sale_v1(uuid,text,text,jsonb)'::regprocedure)like'%v_credit<>v_sale.grand_total%','mixed store credit fails closed');
select ok(pg_get_functiondef(signature::regprocedure)like'%erp_require_command_access_v1%',format('%s checks access',signature))from unnest(array['public.erp_command_create_party_v1(uuid,text,text,jsonb)','public.erp_command_create_catalog_item_v1(uuid,text,text,jsonb)','public.erp_command_receive_inventory_v1(uuid,text,text,jsonb)','public.erp_command_open_cash_v1(uuid,text,text,jsonb)','public.erp_command_complete_sale_v1(uuid,text,text,jsonb)','public.erp_command_settle_receivable_v1(uuid,text,text,jsonb)','public.erp_command_close_cash_v1(uuid,text,text,jsonb)'])signature;
select ok(pg_get_functiondef(signature::regprocedure)like'%erp_claim_command_v1%',format('%s claims receipt',signature))from unnest(array['public.erp_command_create_party_v1(uuid,text,text,jsonb)','public.erp_command_create_catalog_item_v1(uuid,text,text,jsonb)','public.erp_command_receive_inventory_v1(uuid,text,text,jsonb)','public.erp_command_open_cash_v1(uuid,text,text,jsonb)','public.erp_command_complete_sale_v1(uuid,text,text,jsonb)','public.erp_command_settle_receivable_v1(uuid,text,text,jsonb)','public.erp_command_close_cash_v1(uuid,text,text,jsonb)'])signature;
select ok(pg_get_functiondef('public.erp_command_complete_sale_v1(uuid,text,text,jsonb)'::regprocedure)like'%pg_advisory_xact_lock%','sale wrapper locks aggregate');
select ok(pg_get_functiondef('public.erp_command_settle_receivable_v1(uuid,text,text,jsonb)'::regprocedure)like'%pg_advisory_xact_lock%','settlement wrapper locks aggregate');
select ok(pg_get_functiondef('public.erp_command_close_cash_v1(uuid,text,text,jsonb)'::regprocedure)like'%for update%','cash close locks session row');
select*from finish();rollback;
